# Filter out the "... previously defined" id uniqueness validation warnings
# from line 1162 of ref_resolver.py in the schema_salad library.
# TODO: Figure out if there is a problem with our autogenerated CWL.
class NoPreviouslyDefinedFilter(logging.Filter):
    # pylint:disable=too-few-public-methods
    def filter(self, record: logging.LogRecord) -> bool:
        return not record.getMessage().endswith('previously defined')


class NoResolvedFilter(logging.Filter):
    # pylint:disable=too-few-public-methods
    def filter(self, record: logging.LogRecord) -> bool:
        m = re.match(r"Resolved '.*' to '.*'", record.getMessage())
        return not bool(m)  # (True if m else False)


def logging_filters() -> None:
    """Install logging filters that silence known-noisy cwltool/salad log messages."""
    logger_salad = logging.getLogger("salad")
    logger_salad.addFilter(NoPreviouslyDefinedFilter())
    logger_cwltool = logging.getLogger("cwltool")
    logger_cwltool.addFilter(NoResolvedFilter())


def validate_cwl(cwl_path_str: str) -> None:
    """Validate a CWL file using `cwltool.load_tool`.

    Args:
        cwl_path_str (str): The path to the CWL file.
    """
    # NOTE: This uses NoResolvedFilter to suppress the info messages to stdout.
    loading_context, workflowobj, uri = cwltool.load_tool.fetch_document(cwl_path_str)
    loading_context, uri = cwltool.load_tool.resolve_and_validate_document(
        loading_context, workflowobj, uri, preprocess_only=False
    )
    # NOTE: Although resolve_and_validate_document does some validation,
    # some additional validation is done in make_tool, i.e.
    # resolve_and_validate_document does not in fact throw an exception for
    # some invalid CWL files, but make_tool does!
    cwltool.load_tool.make_tool(uri, loading_context)


#: Per `(stem, namespace)`, every file that defines it, in the order found, keyed by real path.
_Definitions: TypeAlias = dict[StepId, dict[str, str]]


def _generated_below(root: str, basepath: str | Path) -> Path | None:
    """The directory Sophios writes into, as a real path, when it lies below the search path `root`; else None.

    A base path that is the search path itself, or outside it, hides nothing: files beside the tools
    are as likely to be tools as not, and a directory outside the search path is never read.
    """
    generated = Path(os.path.realpath(basepath))
    real_root = Path(os.path.realpath(root))
    return generated if generated != real_root and generated.is_relative_to(real_root) else None


def _discoverable_paths(root: str, extension: str, basepath: str | Path) -> list[str]:
    """The files `**/*.{extension}` under the search path `root`, sorted, that may be plugins: not
    something the compiler wrote.

    That is nothing under a directory named `autogenerated`, the default base path, wherever it is
    below `root`, and nothing under `basepath`, the base path in use when it is below `root`.
    Only the part below `root` counts, so a search path that itself sits under `autogenerated/` still works.
    """
    generated = _generated_below(root, basepath)
    found = glob.glob(str(Path(root) / f'**/*.{extension}'), recursive=True)
    return sorted(path for path in found
                  if DEFAULT_BASEPATH not in Path(os.path.relpath(path, root)).parts
                  and (generated is None or not Path(os.path.realpath(path)).is_relative_to(generated)))


def _record(definitions: _Definitions, key: StepId, path: str) -> None:
    """Note that `path` defines `key`.

    A file reached again through overlapping search paths is one file, found at its last visit: that visit wins.
    """
    real_path = os.path.realpath(path)
    files = definitions.setdefault(key, {})
    files.pop(real_path, None)
    files[real_path] = path


def _warn_duplicates(kind: str, definitions: _Definitions) -> None:
    """Say which file each repeated stem resolved to, and why."""
    for key in sorted(definitions, key=lambda k: (k.plugin_ns, k.stem)):
        files = list(definitions[key].values())
        if len(files) < 2:
            continue
        print(f'Warning! {kind} {key.stem!r} in namespace {key.plugin_ns!r} is defined by '
              f'{len(files)} files:', file=sys.stderr)
        for path in files:
            print(f'  {path}', file=sys.stderr)
        print(f'Using {files[-1]}: it is the last one found (search paths in the order the '
              'config lists them, then files in sorted path order).', file=sys.stderr)
        print('To use another, list its search path later, rename one, or put it in a '
              'different namespace.', file=sys.stderr)


def get_tools_cwl(config: Json, validate_plugins: bool = False,
                  basepath: str | Path = DEFAULT_BASEPATH) -> Tools:
    """Uses glob() to find all of the CWL CommandLineTool definition files within the configured search paths

    A stem found more than once in a namespace prints a warning, and the later definition wins:
    search paths in the order the config lists them, then files in sorted path order.

    Args:
        config (Json): The user specified (or default generated) config json object
        validate_plugins (bool, optional): Performs validation on all CWL CommandLineTools. Defaults to False.
        basepath (str | Path, optional): The directory Sophios writes generated files into: `--basepath`, or
            `Workflow.run(basepath=)`. Nothing under it is a tool. Defaults to `autogenerated`.

    Returns:
        Tools: The CWL CommandLineTool definitions found using glob()
    """
    cwl_dirs_tag = config['search_paths_cwl']
    # Load ALL of the tools.
    tools_cwl: Tools = {}
    definitions: _Definitions = {}
    for plugin_ns in cwl_dirs_tag:
        for cwl_dir in cwl_dirs_tag[plugin_ns]:
            # "PurePath.relative_to() requires self to be the subpath of the argument, but os.path.relpath() does not."
            # See https://docs.python.org/3/library/pathlib.html#id4 and
            # See https://stackoverflow.com/questions/67452690/pathlib-path-relative-to-vs-os-path-relpath
            cwl_paths = _discoverable_paths(cwl_dir, 'cwl', basepath)
            if len(cwl_paths) == 0:
                print(f'Warning! No cwl files found in {cwl_dir}.')
                print("Check 'search_paths_cwl' in your config file")
                print('This almost certainly means you are not in the correct directory.')

            for cwl_path_str in cwl_paths:
                if 'biobb_md' in cwl_path_str:
                    continue  # biobb_md is deprecated (in favor of biobb_gromacs)
                with open(cwl_path_str, mode='r', encoding='utf-8') as f:
                    tool: Cwl = utils_cwl.tool_process(yaml.safe_load(f.read()), cwl_path_str)
                stem = Path(cwl_path_str).stem

                if validate_plugins:
                    validate_cwl(cwl_path_str)

                tool = utils_cwl.desugar_into_canonical_normal_form(tool)
                cwl_path_abs = os.path.abspath(cwl_path_str)
                _record(definitions, StepId(stem, plugin_ns), cwl_path_abs)
                tools_cwl[StepId(stem, plugin_ns)] = Tool(cwl_path_abs, tool)
    _warn_duplicates('tool', definitions)
    return tools_cwl


Client: TypeAlias = docker.DockerClient | podman.PodmanClient  # type: ignore


def remove_entrypoints(client: Client, build: Any) -> None:
    """remove/overwrite the entrypoints from all images

    https://cwl.discourse.group/t/override-docker-entrypoint-in-command-line-tool/695/2
    "Here is what the CWL standards have to say about software container entrypoints"
    "I recommend changing your docker container to not use ENTRYPOINT."

    This script will remove / overwrite the entrypoints in ALL of the docker images on your local machine.
    (It will append -noentrypoint to the version tag.)

    The reason is that we want to simultaneously allow
    1. release environments, where users will simply run code in a docker image and
    2. dev/test environments, where developers can run the latest code on the host machine and/or in the CI.

    With entrypoints, there is no easy way to switch between 1 and 2; developers will
    have to manually prepend the entrypoint string to the baseCommand, and/or possibly
    modify paths to be w.r.t. their host machine instead of w.r.t. the image. (/opt/.../main.py)

    Without entrypoints, to switch between 1 and 2, simply comment out DockerRequirement ... that's it!
    The point is that we want a uniform API so that we can programmatically switch between 1 and 2 in the CI.
    We want to run the integration tests first, and only push releases to dockerhub
    when the tests pass (NOT vice versa!).
    """
    # Get a list of all Docker images
    images = client.images.list()

    # Iterate over each container
    for image in images:
        if len(image.attrs['RepoTags']) != 0 and len(image.tags) != 0:
            for tag in image.tags:
                if tag.endswith('-noentrypoint'):
                    continue

                # Define the content of the Dockerfile
                dockerfile_content = f'''
                FROM {tag}
                ENTRYPOINT []
                '''
                with tempfile.TemporaryDirectory() as tempdir:
                    with open(tempdir + '/Dockerfile_tmp', mode='w', encoding='utf-8') as f:
                        f.write(dockerfile_content)

                    # Build the new Docker image from the Dockerfile
                    build.build(
                        path=tempdir,
                        dockerfile="Dockerfile_tmp",
                        tag=f"{tag}-noentrypoint"
                    )


def _docker_requirement(cwl: Cwl, section: str) -> dict[str, Any] | None:
    """The `DockerRequirement` under `cwl[section]`, in either CWL spelling.

    A hand-written adapter spells `requirements`/`hints` as a mapping keyed by
    class; cwl_utils (and so `tool_builder`) spells them as a list of
    `{class: ...}` entries. The entry is returned, not copied, so a caller
    holding a deep copy of `cwl` edits that copy in place.
    """
    entries = cwl.get(section)
    if isinstance(entries, dict):
        found = entries.get('DockerRequirement')
        return found if isinstance(found, dict) else None
    if isinstance(entries, list):
        for entry in entries:
            if isinstance(entry, dict) and entry.get('class') == 'DockerRequirement':
                return entry
    return None


def _noentrypoint_tag(image: str) -> str:
    """`image` with -noentrypoint appended to its tag; `latest` when it names none.

    The tag is read from the last path segment only, so a registry port is not a tag.
    A digest-pinned image has no tag and no built variant, so it is returned unchanged.
    """
    if '@' in image:
        return image
    path, _, name = image.rpartition('/')
    repo, _, tag = name.partition(':')
    if tag.endswith('-noentrypoint'):
        return image
    prefix = f'{path}/' if path else ''
    return f"{prefix}{repo}:{tag or 'latest'}-noentrypoint"


def _append_noentrypoint_in_place(process: Cwl) -> None:
    """Tag every `DockerRequirement` of `process` and of each process embedded in its steps."""
    for section in ('requirements', 'hints'):
        requirement = _docker_requirement(process, section)
        if requirement is not None and requirement.get('dockerPull'):
            requirement['dockerPull'] = _noentrypoint_tag(requirement['dockerPull'])
    steps = process.get('steps', [])
    for step in steps.values() if isinstance(steps, dict) else steps:
        if isinstance(step, dict) and isinstance(step.get('run'), dict):
            _append_noentrypoint_in_place(step['run'])


def dockerPull_append_noentrypoint(cwl: Cwl) -> Cwl:
    """`cwl` naming the no-entrypoint images `--docker_remove_entrypoints` builds.

    Every `dockerPull` the runner reads gets -noentrypoint appended to its tag: under
    `requirements` or `hints`, of the document and of every process embedded in its
    steps, at any depth. `cwl` itself is not changed.
    """
    cwl_noentrypoint = copy.deepcopy(cwl)
    _append_noentrypoint_in_place(cwl_noentrypoint)
    return cwl_noentrypoint


def dockerPull_append_noentrypoint_artifact(
        artifact: CompilationArtifact) -> CompilationArtifact:
    """Append the no-entrypoint tag throughout an artifact tree."""
    return replace(
        artifact,
        cwl=dockerPull_append_noentrypoint(artifact.cwl),
        children=tuple(dockerPull_append_noentrypoint_artifact(child)
                       for child in artifact.children),
    )


def get_workflow_paths(config: Json, extension: str,
                       basepath: str | Path = DEFAULT_BASEPATH) -> dict[str, dict[str, Path]]:
    """Uses glob() to recursively find all of the yml workflow definition files
    within any subdirectory of each yml_dir in search_paths_wic.
    NOTE: This function assumes all yml files found are workflow definition files,
    so do not mix regular yml files and workflow files in the same root directory.
    A stem found more than once in a namespace prints a warning, and the later definition wins:
    yml_dirs in the order the config lists them, then files in sorted path order.

    Args:
        config (Json): The user specified (or default generated) config json object
        extension (str): The filename extension (either 'wic' or 'py')
        basepath (str | Path, optional): The directory Sophios writes generated files into. Nothing under it is
            a workflow. Defaults to `autogenerated`.

    Returns:
        dict[str, dict[str, Path]]: A dict containing the filepath stem and filepath of each yml file
    """
    search_paths_wic_tag = config['search_paths_wic']
    # Glob all of the yml files too, so we don't have to deal with relative paths.
    yml_paths_all: dict[str, dict[str, Path]] = {}
    definitions: _Definitions = {}
    for yml_namespace in search_paths_wic_tag:
        yml_dirs = search_paths_wic_tag[yml_namespace]
        for yml_dir in yml_dirs:
            # "PurePath.relative_to() requires self to be the subpath of the argument, but os.path.relpath() does not."
            # See https://docs.python.org/3/library/pathlib.html#id4 and
            # See https://stackoverflow.com/questions/67452690/pathlib-path-relative-to-vs-os-path-relpath
            yml_paths_sorted = _discoverable_paths(yml_dir, extension, basepath)
            if len(yml_paths_sorted) == 0:
                print(f'Warning! No {extension} files found in {yml_dir}.')
                print("Check 'search_paths_wic' in your config file")
                print('This almost certainly means you are not in the correct directory.')
            yml_paths = {}
            for yml_path_str in yml_paths_sorted:
                # Exclude our autogenerated inputs files
                if '_inputs' not in yml_path_str:
                    yml_path = Path(yml_path_str)
                    yml_path_abs = os.path.abspath(yml_path_str)
                    _record(definitions, StepId(yml_path.stem, yml_namespace), yml_path_abs)
                    yml_paths[yml_path.stem] = Path(yml_path_abs)
            # Check for existing entry
            ns_dict = yml_paths_all.get(yml_namespace, {})
            yml_paths_all[yml_namespace] = {**ns_dict, **yml_paths}

    _warn_duplicates('workflow', definitions)
    return yml_paths_all


def get_yml_paths(config: Json, basepath: str | Path = DEFAULT_BASEPATH) -> dict[str, dict[str, Path]]:
    """Find all `.wic` workflow definition files. See `get_workflow_paths`."""
    return get_workflow_paths(config, 'wic', basepath)
